P = {}
def add(cid, pred, basis, conf, trig=None):
    t = trig or {"changed_main": False, "reserve_used": False, "disputed": False, "reason": "主用神自候选枚举至终局未改定；未取伏神/备用用神；取用无并列存疑。"}
    P[cid] = {"case_id": cid, "prediction_text": pred, "basis": basis, "confidence": conf, "trigger": t}

